def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Continue each diagonal formed by a neighboring same-color pair.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr in (-1, 1):
                for dc in (-1, 1):
                    rr, cc = r + dr, c + dc
                    if not (0 <= rr < h and 0 <= cc < w):
                        continue
                    if grid[rr][cc] != color:
                        continue
                    # Extend beyond each end of the pair; other objects block a ray.
                    for sr, sc in ((-dr, -dc), (dr, dc)):
                        x, y = (r, c) if (sr, sc) == (-dr, -dc) else (rr, cc)
                        while 0 <= x + sr < h and 0 <= y + sc < w:
                            x, y = x + sr, y + sc
                            if grid[x][y] != bg:
                                break
                            out[x][y] = color
    return out
